// ABOUTME: Test-side E2EE client helpers over a MockClientSocket (plan T5).
// ABOUTME: e2ee_hello/e2ee_ready handshake plus sealed send / opened recv.

//! Shared by `tests/relay_control_transport.rs` and `tests/relay_e2e.rs`.
//! The client keypair is throwaway X25519 material via `crypto_box`; the
//! handshake frames are the literal wire shapes from the spec §2.4 table,
//! never generated by round-tripping the daemon's types.

use base64::engine::general_purpose::STANDARD as BASE64_STANDARD;
use base64::Engine;
use picot_host::relay::e2ee;

use super::mock_relay::MockClientSocket;

/// A throwaway client keypair for one data connection: X25519 via
/// `crypto_box` directly, so the test client shares no key material path
/// with the daemon identity under test.
pub struct ClientKeys {
    secret: [u8; 32],
    public_key_b64: String,
}

pub fn client_keys() -> ClientKeys {
    let secret = crypto_box::SecretKey::generate(&mut rand::rngs::OsRng);
    let public_key_b64 = BASE64_STANDARD.encode(secret.public_key().as_bytes());
    ClientKeys {
        secret: secret.to_bytes(),
        public_key_b64,
    }
}

/// The plaintext `e2ee_hello` frame carrying this client's public key.
pub fn hello_frame(client: &ClientKeys) -> String {
    format!(
        "{{\"type\":\"e2ee_hello\",\"key\":\"{}\"}}",
        client.public_key_b64
    )
}

/// Derive this client's per-connection shared key against the daemon's
/// public key (the offer-embedded trust anchor in production).
pub fn shared_key(client: &ClientKeys, daemon_public_key_b64: &str) -> [u8; 32] {
    e2ee::derive_shared_key(&client.secret, daemon_public_key_b64)
        .expect("client derives the shared key")
}

/// Full client-side handshake: send `e2ee_hello`, await the plaintext
/// `e2ee_ready`, return the per-connection shared key.
pub async fn handshake(socket: &mut MockClientSocket, daemon_public_key_b64: &str) -> [u8; 32] {
    let client = client_keys();
    socket.send_text(&hello_frame(&client)).await;
    let ready = socket.recv_text().await;
    assert_eq!(
        ready, "{\"type\":\"e2ee_ready\"}",
        "daemon must answer the hello with a plaintext e2ee_ready"
    );
    shared_key(&client, daemon_public_key_b64)
}

/// base64(nonce || ciphertext) for a plaintext frame — the wire text.
#[allow(dead_code)] // shared support: per-target subset usage
pub fn seal_text(shared: &[u8; 32], text: &str) -> String {
    BASE64_STANDARD.encode(e2ee::seal(shared, text.as_bytes()))
}

/// Send one encrypted frame.
pub async fn send_sealed(socket: &mut MockClientSocket, shared: &[u8; 32], text: &str) {
    socket.send_text(&seal_text(shared, text)).await;
}

/// Receive the next daemon frame and open it; panics on bad base64, failed
/// decryption, or non-UTF-8 plaintext (all are daemon contract violations).
pub async fn recv_opened(socket: &mut MockClientSocket, shared: &[u8; 32]) -> String {
    let wire = socket.recv_text().await;
    open_wire(shared, &wire)
}

/// Open a wire text against a shared key (shared so tamper tests can flip
/// bytes before sending and assert the daemon's side of the failure).
#[allow(dead_code)] // shared support: per-target subset usage
pub fn open_wire(shared: &[u8; 32], wire: &str) -> String {
    let bundle = BASE64_STANDARD
        .decode(wire)
        .expect("daemon wire frame is base64");
    let plaintext = e2ee::open(shared, &bundle).expect("daemon frame decrypts");
    String::from_utf8(plaintext).expect("daemon plaintext is UTF-8")
}
